4. ConcreteDecorators(MilkDecorator,SugarDecorator)MilkDecorator and SugarDecorator are concrete decorators extending CoffeeDecorator.They override getDescription() to add the respective decorator description to the decorated coffee's description.They override getCost() to add the cost of the respective decorator to the decorated coffee's cost.
            C++

    #include <string>
#include <iostream>

class Coffee {
public:
    virtual std::string getDescription() const = 0;
    virtual double getCost() const = 0;
};

class CoffeeDecorator : public Coffee {
protected:
    Coffee* decoratedCoffee;
public:
    CoffeeDecorator(Coffee* coffee) : decoratedCoffee(coffee) {}
    virtual std::string getDescription() const override {
        return decoratedCoffee->getDescription();
    }
    virtual double getCost() const override {
        return decoratedCoffee->getCost();
    }
};

class MilkDecorator : public CoffeeDecorator {
public:
    MilkDecorator(Coffee* coffee) : CoffeeDecorator(coffee) {}
    std::string getDescription() const override {
        return CoffeeDecorator::getDescription() + ", Milk";
    }
    double getCost() const override {
        return CoffeeDecorator::getCost() + 0.5;
    }
};

class SugarDecorator : public CoffeeDecorator {
public:
    SugarDecorator(Coffee* coffee) : CoffeeDecorator(coffee) {}
    std::string getDescription() const override {
        return CoffeeDecorator::getDescription() + ", Sugar";
    }
    double getCost() const override {
        return CoffeeDecorator::getCost() + 0.2;
    }
};


